mapper.update:
update emp
name = #{name}, gender = #{gender}, entry_date = #{entryDate}, dept_id = #{deptId}, job = #{job}, phone = #{phone}, salary = #{salary}, username = #{username}, password = #{password}, image = #{image}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select e.*, d.name deptName from emp e left join dept d on e.dept_id = d.id


        e.name like concat('%',#{name},'%')


        and e.gender = #{gender}


        and e.entry_date between #{begin} and #{end}


order by e.update_time desc
